package com.geekmall.inventory;
import com.fasterxml.jackson.databind.ObjectMapper;import com.geekmall.common.security.*;import org.junit.jupiter.api.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class InventoryIdempotencyTest{@AfterEach void clear(){TenantContext.clear();}@Test void duplicateInboundReturnsOriginalAndDoesNotTouchStock(){JdbcTemplate jdbc=mock(JdbcTemplate.class);doThrow(new DuplicateKeyException("duplicate")).when(jdbc).update(startsWith("INSERT INTO inventory_idempotency"),any(),any(),any());when(jdbc.queryForObject(startsWith("SELECT result_ref"),eq(String.class),any(),any())).thenReturn("IN-ORIGINAL");InventoryService service=new InventoryService(jdbc,new ObjectMapper());TenantContext.setMerchantId(2001L);var principal=new AuthPrincipal(2,"merchant_a","BACKOFFICE",2001L,3001L,Set.of("MERCHANT"),Set.of("merchant:product:view"));var result=service.inbound(new InventoryController.InboundRequest(9001L,11001L,5),"same-key",principal);assertThat(result).containsEntry("businessNo","IN-ORIGINAL").containsEntry("idempotentReplay",true);verify(jdbc,never()).update(startsWith("UPDATE inventory_sku_stock"),any(),any(),any());}}
